/// v12〜v14 凍結時点の forward pass（25次元）。opp_move_nn_forward の当時のコピー
pub fn opp_move_nn_forward25(features: &[f64; 25]) -> f64 {
    let mut x = [0.0f64; 25];
    for i in 0..25 {
        x[i] = (features[i] - OPP_MOVE_NN_V25_MEAN[i]) / OPP_MOVE_NN_V25_STD[i];
    }
    let mut h = [0.0f64; 16];
    for j in 0..16 {
        let mut s = OPP_MOVE_NN_V25_B1[j];
        for i in 0..25 {
            s += OPP_MOVE_NN_V25_W1[j][i] * x[i];
        }
        h[j] = s.max(0.0); // ReLU
    }
    let mut out = OPP_MOVE_NN_V25_B2;
    for j in 0..16 {
        out += OPP_MOVE_NN_V25_W2[j] * h[j];
    }
    out
}

